    /**
     * Method to retrieve the Account via an AccountPrimaryKey.
     * @param 	id Long
     * @return 	Account
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Account handle( FindAccountQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAccountId() );
    }
    
    /**
     * Method to retrieve a collection of all Accounts
     *
     * @param	query	FindAllAccountQuery 
     * @return 	List<Account> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Account> handle( FindAllAccountQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAccount,
 * but only if the id matches
 *
 * @param		entity	Account
 */
	protected void emitFindAccount( Account entity ) {
		LOGGER.info("handling emitFindAccount" );
		
	    queryUpdateEmitter.emit(FindAccountQuery.class,
	                            query -> query.getFilter().getAccountId().equals(entity.getAccountId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAccount
	 * 
	 * @param		entity	Account
	 */
	protected void emitFindAllAccount( Account entity ) {
		LOGGER.info("handling emitFindAllAccount" );
		
	    queryUpdateEmitter.emit(FindAllAccountQuery.class,
	                            query -> true,
	                            entity);
	}

